            "type": "code",
            "text": "#include <stdio.h>\nstruct Student {\nint rollNo;\nchar name[30];\nfloat marks;\n};\nint main() {\nstruct Student s1 = {101, \"Ravi\", 89.5};\nprintf(\"Student Details\\n\");\nprintf(\"Roll No: %d\\n\", s1.rollNo);\nprintf(\"Name: %s\\n\", s1.name);\nprintf(\"Marks: %.2f\\n\", s1.marks);\nreturn 0;\n}"
