            "type": "code",
            "text": "a, b = map(int, input(\"Enter range: \").split())\n\nfor n in range(a, b+1):\n if n > 1:\n for i in range(2, int(n**0.5) + 1):\n if n % i == 0:\n break\n else:\n print(n, end=\" \")"
